package clinic.harbour.web;

import clinic.harbour.domain.*;
import clinic.harbour.security.ActingUser;
import clinic.harbour.service.ClinicService;
import jakarta.enterprise.context.RequestScoped;
import jakarta.inject.Inject;
import jakarta.inject.Named;
import java.time.*;
import java.util.*;

@Named @RequestScoped
public class PortalBean {
    @Inject ClinicService clinic;
    private List<Appointment> appointments;private List<Patient> patients;private Long patientId;private String patientQuery,status,sort="startsAt",reason,type;private long providerId,appointmentId;private LocalDate appointmentDate=LocalDate.now().plusDays(7),from,to;private String appointmentTime="09:00",transition,rescheduleNote,phone,email,address,emergency;
    public ActingUser getActor(){return clinic.actor();}public boolean isPatient(){return getActor().role()==Role.PATIENT;}public boolean isClinician(){return getActor().role()==Role.CLINICIAN;}public boolean isFrontDesk(){return getActor().role()==Role.FRONT_DESK;}public boolean isAdmin(){return getActor().role()==Role.CLINIC_ADMIN;}public boolean isStaff(){return getActor().staff();}
    public List<Appointment> getAppointments(){if(appointments==null)appointments=clinic.appointments(status,from,to,sort);return appointments;}public List<Provider> getProviders(){return clinic.providers();}public List<AppointmentType> getAppointmentTypes(){return clinic.appointmentTypes();}public List<Patient> getPatients(){if(patients==null)patients=clinic.patients(patientQuery);return patients;}public List<Notification> getNotifications(){return clinic.notifications();}
    public Patient getSelectedPatient(){if(patientId==null){ActingUser a=getActor();if(a.patientId()!=null)patientId=a.patientId();}return patientId==null?null:clinic.patient(patientId);}public List<VisitSummary> getVisits(){Patient p=getSelectedPatient();return p==null?List.of():clinic.visitsFor(p.getId());}public List<Prescription> getPrescriptions(){Patient p=getSelectedPatient();return p==null?List.of():clinic.prescriptionsFor(p.getId());}
    public void book(){try{Instant start=LocalDateTime.of(appointmentDate,LocalTime.parse(appointmentTime)).toInstant(ZoneOffset.UTC);clinic.book(providerId,type,start,reason);Flash.success("Appointment requested. The clinic will confirm it shortly.");reason=null;appointments=null;}catch(RuntimeException e){Flash.error(e);}}
    public void transition(){try{clinic.transitionAppointment(appointmentId,Statuses.AppointmentStatus.valueOf(transition));Flash.success("Appointment status updated.");appointments=null;}catch(RuntimeException e){Flash.error(e);}}
    public void reschedule(){try{Instant start=LocalDateTime.of(appointmentDate,LocalTime.parse(appointmentTime)).toInstant(ZoneOffset.UTC);clinic.reschedule(appointmentId,providerId,start,rescheduleNote);Flash.success("Appointment rescheduled.");appointments=null;}catch(RuntimeException e){Flash.error(e);}}
    public void closeOutBoard(){try{int count=clinic.completeDayBoard(appointmentDate);Flash.success(count+" appointments closed out for "+appointmentDate+".");appointments=null;}catch(RuntimeException e){Flash.error(e);}}
    public void requestRefill(long id){try{clinic.requestRefill(id,"Patient requested a refill through the portal.");Flash.success("Refill request sent to your clinician.");}catch(RuntimeException e){Flash.error(e);}}
    public void updateDemographics(){try{clinic.updateDemographics(patientId,phone,email,address,emergency);Flash.success("Patient demographics updated.");}catch(RuntimeException e){Flash.error(e);}}
    public int getUpcomingCount(){return (int)getAppointments().stream().filter(a->a.getStartsAt().isAfter(Instant.now())&&Set.of(Statuses.AppointmentStatus.REQUESTED,Statuses.AppointmentStatus.SCHEDULED).contains(a.getStatus())).count();}public int getUnreadCount(){return (int)getNotifications().stream().filter(n->n.getReadAt()==null).count();}
    public Long getPatientId(){return patientId;}public void setPatientId(Long v){patientId=v;}public String getPatientQuery(){return patientQuery;}public void setPatientQuery(String v){patientQuery=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getSort(){return sort;}public void setSort(String v){sort=v;}public String getReason(){return reason;}public void setReason(String v){reason=v;}public String getType(){return type;}public void setType(String v){type=v;}public long getProviderId(){return providerId;}public void setProviderId(long v){providerId=v;}public LocalDate getAppointmentDate(){return appointmentDate;}public void setAppointmentDate(LocalDate v){appointmentDate=v;}public String getAppointmentTime(){return appointmentTime;}public void setAppointmentTime(String v){appointmentTime=v;}public LocalDate getFrom(){return from;}public void setFrom(LocalDate v){from=v;}public LocalDate getTo(){return to;}public void setTo(LocalDate v){to=v;}public long getAppointmentId(){return appointmentId;}public void setAppointmentId(long v){appointmentId=v;}public String getTransition(){return transition;}public void setTransition(String v){transition=v;}public String getRescheduleNote(){return rescheduleNote;}public void setRescheduleNote(String v){rescheduleNote=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getEmergency(){return emergency;}public void setEmergency(String v){emergency=v;}
}
